-- 3. Insert the 25 Featured Southampton Events
INSERT INTO public.events (
    id, society_id, title, description, location, category, tags, food_detail, 
    latitude, longitude, external_link, image_url, starts_at, ends_at, created_at, updated_at
) VALUES 
-- NIGHTLIFE & SOCIALS
('22222222-2222-4222-a222-000000000001', '11111111-1111-4111-a111-000000000001', 'Jesters Monday Shoes Defiler', 'The legendary Jesters Monday. Wear shoes you never want to see clean again. 4-pint jugs of Jesticle await.', 'Jesters Nightclub, Bevois Valley', 'social', ARRAY['Nightlife', '18+', 'Soton Classic'], null, 50.9161, -1.3980, null, 'https://images.unsplash.com/photo-1574393664320-94e8db036b53?w=800&q=80', NOW() + INTERVAL '1 day' + INTERVAL '22 hours', NOW() + INTERVAL '1 day' + INTERVAL '26 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000002', '11111111-1111-4111-a111-000000000002', 'Sobar Tuesdays: R&B Night', '£1.50 doubles before midnight! The ultimate student Tuesday night out at Sobar in Bevois Valley.', 'Sobar, Bevois Valley', 'social', ARRAY['Music', 'Party', 'Student Drink Promos'], null, 50.9160, -1.3982, null, 'https://images.unsplash.com/photo-1545128485-c400e7702796?w=800&q=80', NOW() + INTERVAL '2 days' + INTERVAL '22 hours', NOW() + INTERVAL '2 days' + INTERVAL '25 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000003', '11111111-1111-4111-a111-000000000001', 'SUSU Saturday: Neon Rave', 'The Basement is transforming into a neon wonderland. Glow sticks, UV paint, and drum & bass.', 'The Cube, SUSU Building 42', 'social', ARRAY['Rave', 'D&B', 'On Campus'], null, 50.9341, -1.3966, 'https://susu.org/events', 'https://images.unsplash.com/photo-1514525253361-ca6515f39230?w=800&q=80', NOW() + INTERVAL '5 days' + INTERVAL '22 hours', NOW() + INTERVAL '5 days' + INTERVAL '27 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000004', '11111111-1111-4111-a111-000000000003', 'Trago Lounge Cocktail Masterclass', 'Learn to mix 3 classic cocktails with the Cocktail Society. Ingredients and shakers provided!', 'Trago Lounge, Portswood', 'social', ARRAY['Mixology', 'Chill'], 'Cocktails', 50.9255, -1.3951, null, 'https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?w=800&q=80', NOW() + INTERVAL '3 days' + INTERVAL '19 hours', NOW() + INTERVAL '3 days' + INTERVAL '21 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000005', '11111111-1111-4111-a111-000000000004', 'Café Thrive Board Game Café', 'Casual board games, vegan snacks, and good vibes. Bring your own games or play ours!', 'Café Thrive, Hanover Buildings', 'social', ARRAY['Sober', 'Vegan Friendly', 'Chill'], 'Vegan Snacks', 50.9025, -1.4035, null, 'https://images.unsplash.com/photo-1610890716171-6b1bb98ffaed?w=800&q=80', NOW() + INTERVAL '4 days' + INTERVAL '14 hours', NOW() + INTERVAL '4 days' + INTERVAL '17 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000006', '11111111-1111-4111-a111-000000000005', 'Karaoke at The Stag''s', 'Warm up your vocal cords. Every Thursday is Karaoke night at the campus pub!', 'The Stag''s Head Pub, SUSU', 'social', ARRAY['Karaoke', 'Campus Pub', 'Free'], null, 50.9341, -1.3966, null, 'https://images.unsplash.com/photo-1516280440502-613861d85fb4?w=800&q=80', NOW() + INTERVAL '3 days' + INTERVAL '20 hours', NOW() + INTERVAL '3 days' + INTERVAL '23 hours', NOW(), NOW()),

-- SPORTS & ATHLETICS
('22222222-2222-4222-a222-000000000007', '11111111-1111-4111-a111-000000000006', 'Varsity Rugby: Soton vs Portsmouth', 'The biggest rivalry on the south coast! Support Team Southampton as we take on Pompey at home.', 'Wide Lane Sports Grounds', 'sports', ARRAY['Varsity', 'Rugby', 'Spectator'], 'Burger Van', 50.9571, -1.3789, 'https://susu.org/sports', 'https://images.unsplash.com/photo-1543661858-debd0eb79b94?w=800&q=80', NOW() + INTERVAL '6 days' + INTERVAL '14 hours', NOW() + INTERVAL '6 days' + INTERVAL '17 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000008', '11111111-1111-4111-a111-000000000007', 'Surf Soc Weekend Trip Briefing', 'Pre-trip Briefing for the upcoming Newquay weekend trip. Mandatory for all ticket holders!', 'Building 174, Room 1021', 'meeting', ARRAY['Surfing', 'Trip Briefing'], null, 50.9360, -1.3970, null, 'https://images.unsplash.com/photo-1502680390469-be75c86b636f?w=800&q=80', NOW() + INTERVAL '1 day' + INTERVAL '18 hours', NOW() + INTERVAL '1 day' + INTERVAL '19 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000009', '11111111-1111-4111-a111-000000000008', 'Boulder Shack Intro Session', 'Never climbed before? Join us at Boulder Shack! Free shoe rental for students with valid student ID.', 'Boulder Shack Climbing Gym', 'sports', ARRAY['Climbing', 'Beginners Welcome'], null, 50.9315, -1.3900, 'https://bouldershack.co.uk/', 'https://images.unsplash.com/photo-1522163182402-834f871fd851?w=800&q=80', NOW() + INTERVAL '2 days' + INTERVAL '16 hours', NOW() + INTERVAL '2 days' + INTERVAL '18 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000010', '11111111-1111-4111-a111-000000000006', 'Jubilee Gym Inductions', 'New to the campus gym? Get a free 30-minute induction showing you how to use the equipment safely.', 'Jubilee Sports Centre', 'sports', ARRAY['Fitness', 'Free', 'Campus'], null, 50.9355, -1.3950, null, 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=800&q=80', NOW() + INTERVAL '10 hours', NOW() + INTERVAL '18 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000011', '11111111-1111-4111-a111-000000000009', 'Intramural Tennis League Finals', 'Watch the campus intramural league finals! Open to all spectators.', 'Avenue Campus Tennis Courts', 'sports', ARRAY['Tennis', 'Finals', 'Free'], null, 50.9288, -1.4011, null, 'https://images.unsplash.com/photo-1595435934249-5df7ed86e1c0?w=800&q=80', NOW() + INTERVAL '4 days' + INTERVAL '12 hours', NOW() + INTERVAL '4 days' + INTERVAL '15 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000012', '11111111-1111-4111-a111-000000000010', 'Learn to Row - Tryout #2', 'Wessex Southampton Boat Club invites you to try rowing! Meet at the boat house.', 'Southampton University Boat House, River Itchen', 'sports', ARRAY['Rowing', 'Water Sports'], null, 50.9351, -1.3780, null, 'https://images.unsplash.com/photo-1535694206001-f2f29b71e72e?w=800&q=80', NOW() + INTERVAL '3 days' + INTERVAL '7 hours', NOW() + INTERVAL '3 days' + INTERVAL '9 hours', NOW(), NOW()),

-- ACADEMICS & WORKSHOPS
('22222222-2222-4222-a222-000000000013', '11111111-1111-4111-a111-000000000011', 'React & Vite BootCamp', 'A 2-hour intensive fast-track to building frontend web apps by ECSS. Free pizza halfway through!', 'Building 32 (Zepler), Level 4 Labs', 'workshop', ARRAY['Coding', 'CS', 'Free Pizza'], 'Dominos Pizza', 50.9370, -1.3976, null, 'https://images.unsplash.com/photo-1633356122544-f134324a6cee?w=800&q=80', NOW() + INTERVAL '1 day' + INTERVAL '15 hours', NOW() + INTERVAL '1 day' + INTERVAL '17 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000014', '11111111-1111-4111-a111-000000000012', 'Hartley Library: Referencing 101', 'Struggling with Harvard referencing? Join the Academic Skills hub for a quick masterclass.', 'Hartley Library, Level 2 Training Room', 'workshop', ARRAY['Study Skills', 'Academic'], null, 50.9358, -1.3978, 'https://library.soton.ac.uk/', 'https://images.unsplash.com/photo-1541339907198-e08756dedf3f?w=800&q=80', NOW() + INTERVAL '2 days' + INTERVAL '13 hours', NOW() + INTERVAL '2 days' + INTERVAL '14 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000015', '11111111-1111-4111-a111-000000000013', 'MedSoc: OSCE Mock Scenarios', 'Practice for your OSCEs with senior years running mock wards. Open to Y2-Y4 Med Students.', 'Southampton General Hospital, SGH Skills Lab', 'workshop', ARRAY['Medicine', 'Study'], null, 50.9329, -1.4285, null, 'https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=800&q=80', NOW() + INTERVAL '3 days' + INTERVAL '17 hours', NOW() + INTERVAL '3 days' + INTERVAL '20 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000016', '11111111-1111-4111-a111-000000000014', 'Bloomberg Terminal Training', 'Learn how to navigate and strictly analyze markets using the Bloomberg Terminals in the Business School.', 'Building 2 (Music/Business), Room 1022', 'workshop', ARRAY['Finance', 'Business School'], null, 50.9353, -1.3965, null, 'https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?w=800&q=80', NOW() + INTERVAL '5 days' + INTERVAL '14 hours', NOW() + INTERVAL '5 days' + INTERVAL '16 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000017', '11111111-1111-4111-a111-000000000015', 'Mooting Competition Quarter-Finals', 'Watch the Law Society quarter-finalists battle it out in a simulated courtroom environment.', 'Building 4, Moot Court Room', 'meeting', ARRAY['Law', 'Debate', 'Spectator'], null, 50.9348, -1.3960, null, 'https://images.unsplash.com/photo-1589391886645-d51941baf7fb?w=800&q=80', NOW() + INTERVAL '4 days' + INTERVAL '18 hours', NOW() + INTERVAL '4 days' + INTERVAL '21 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000018', '11111111-1111-4111-a111-000000000016', 'Life Drawing at Winchester School of Art', 'Take the shuttle bus to WSA for a relaxed 2-hour life drawing session. Charcoal and paper provided.', 'Winchester School of Art', 'workshop', ARRAY['Art', 'WSA Campus'], null, 51.0650, -1.3114, null, 'https://images.unsplash.com/photo-1513364776144-60967b0f800f?w=800&q=80', NOW() + INTERVAL '6 days' + INTERVAL '16 hours', NOW() + INTERVAL '6 days' + INTERVAL '18 hours', NOW(), NOW()),

-- FREEBIES, FOOD, MISC
('22222222-2222-4222-a222-000000000019', '11111111-1111-4111-a111-000000000001', 'Plant Sale on the Concourse', 'Brighten up your uni room! Huge selection of succulents, snake plants, and monsteras starting at £3.', 'Red Brick Area (Outside SUSU)', 'social', ARRAY['Plants', 'Shopping', 'Campus'], null, 50.9342, -1.3966, null, 'https://images.unsplash.com/photo-1466692476868-aef1dfb1e735?w=800&q=80', NOW() + INTERVAL '1 day' + INTERVAL '10 hours', NOW() + INTERVAL '1 day' + INTERVAL '16 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000020', '11111111-1111-4111-a111-000000000017', 'Spring Career Fair: Tech & Engineering', 'Over 50 employers including BAE Systems, Google, and Dyson looking for summer interns and grads.', 'Jubilee Sports Hall', 'meeting', ARRAY['Careers', 'Networking', 'Internships'], 'Free corporate swag', 50.9355, -1.3950, 'https://soton.ac.uk/careers', 'https://images.unsplash.com/photo-1556761175-4b46a572b786?w=800&q=80', NOW() + INTERVAL '7 days' + INTERVAL '11 hours', NOW() + INTERVAL '7 days' + INTERVAL '15 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000021', '11111111-1111-4111-a111-000000000018', 'Pancake Day Free Breakfast', 'Free vegan pancakes with maple syrup and berries to celebrate Pancake Day! First come, first served.', ' SUSU Redbrick / Concourse', 'social', ARRAY['Free Food', 'Vegan', 'Breakfast'], 'Pancakes', 50.9341, -1.3966, null, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=800&q=80', NOW() + INTERVAL '2 days' + INTERVAL '9 hours', NOW() + INTERVAL '2 days' + INTERVAL '11 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000022', '11111111-1111-4111-a111-000000000019', 'Puppy Therapy Session', 'Take a break from studying! Guide Dogs UK are bringing 10 puppies to campus to help relieve exam stress.', 'Building 42 (SUSU), The Bridge', 'social', ARRAY['Wellbeing', 'Dogs', 'Stress Relief'], null, 50.9341, -1.3966, null, 'https://images.unsplash.com/photo-1546527868-ccb7ee7fdad9?w=800&q=80', NOW() + INTERVAL '3 days' + INTERVAL '13 hours', NOW() + INTERVAL '3 days' + INTERVAL '16 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000023', '11111111-1111-4111-a111-000000000020', 'Union Films: Interstellar (70mm)', 'Experience Nolan''s masterpiece in highest quality. Cinematic surround sound in the Union Films theatre.', 'Union Films, SUSU Level 3', 'social', ARRAY['Cinema', 'Film', 'Sci-Fi'], 'Popcorn', 50.9341, -1.3966, 'https://unionfilms.org/', 'https://images.unsplash.com/photo-1440404653325-ab127d49abc1?w=800&q=80', NOW() + INTERVAL '4 days' + INTERVAL '20 hours', NOW() + INTERVAL '4 days' + INTERVAL '23 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000024', '11111111-1111-4111-a111-000000000021', 'Grand Iftar on Campus', 'Breaking of the fast together! Free hot meals provided. Everyone of all faiths is welcome to join.', 'The Cube, SUSU', 'social', ARRAY['Faith', 'Free Food', 'Community'], 'Biryani & Dates', 50.9341, -1.3966, null, 'https://images.unsplash.com/photo-1596484552834-6a58f850d0fa?w=800&q=80', NOW() + INTERVAL '5 days' + INTERVAL '18 hours', NOW() + INTERVAL '5 days' + INTERVAL '20 hours', NOW(), NOW()),
('22222222-2222-4222-a222-000000000025', '11111111-1111-4111-a111-000000000022', 'Stargazing at the Soton Observatory', 'Using the university telescopes on the roof of Physics to view Saturn''s rings! Weather permitting.', 'Physics Building 46 Roof Observatory', 'workshop', ARRAY['Astronomy', 'Science', 'Night'], null, 50.9349, -1.3961, null, 'https://images.unsplash.com/photo-1516339901601-2e1b62dc0c45?w=800&q=80', NOW() + INTERVAL '6 days' + INTERVAL '21 hours', NOW() + INTERVAL '6 days' + INTERVAL '23 hours', NOW(), NOW())
ON CONFLICT (id) DO UPDATE SET 
    title = EXCLUDED.title,
    description = EXCLUDED.description,
